// Create an element
let li = document.createElement("li");
li.textContent = "New item";

// Append it to a list
document.querySelector("ul").appendChild(li);

// append() also accepts strings
document.querySelector("ul").append("Text node", li);

// prepend puts it at the top
document.querySelector("ul").prepend("First item");

let el = document.querySelector(".output");

// textContent — safe, escapes HTML
el.textContent = "<b>Hello</b>";
// Shows literal: <b>Hello</b> as text

// innerHTML — renders HTML
el.innerHTML = "<b>Hello</b>";
// Shows: Hello in bold

// DANGER: never do this with user input
let userInput = '<img src=x onerror=alert("XSS")>';
el.innerHTML = userInput;  // executes the script!
el.textContent = userInput; // just displays the text safely

let box = document.querySelector(".box");

// Add classes
box.classList.add("active", "highlighted");

// Remove a class
box.classList.remove("highlighted");

// Toggle a class (click handler pattern)
box.addEventListener("click", () => {
  box.classList.toggle("active");
});

// Check before adding
if (!box.classList.contains("active")) {
  box.classList.add("active");
}

let link = document.querySelector("a");

// Read and write href
console.log(link.getAttribute("href"));
link.setAttribute("href", "https://newsite.com");
link.setAttribute("target", "_blank");

// Data attributes in HTML: <img data-id="5" data-category="shoes">
let img = document.querySelector("img");
console.log(img.dataset.id);        // "5"
console.log(img.dataset.category);  // "shoes"

// Set a new data attribute
img.dataset.price = "29.99";
// Creates: data-price="29.99" in the HTML

// Direct removal
let item = document.querySelector(".item");
item.remove();

// removeChild — returns the removed node
let list = document.querySelector("ul");
let firstItem = list.children[0];
let removed = list.removeChild(firstItem);
console.log(removed.textContent);  // text of removed item

// Remove all children in a loop
while (list.firstChild) {
  list.removeChild(list.firstChild);
}
